CREATE TRIGGER RefCusConditionValue_Combined
	ON RefCusConditionValue
	FOR INSERT, UPDATE, DELETE
	AS
	IF (SELECT CASE WHEN EXISTS(SELECT 1 FROM INSERTED) AND NOT EXISTS(SELECT 1 FROM DELETED) THEN 1 ELSE 0 end) = 1
	BEGIN
		UPDATE t SET
		ZX3_DataSetPK = ZX1_DataSetPK,
		ZX3_DataSetCode = ZX1_DataSetCode
		FROM RefCusConditionValue t
		JOIN inserted ON t.ZX3_PK = inserted.ZX3_PK
		LEFT JOIN RefCusCondition ON inserted.ZX3_ZX1_Condition = ZX1_PK
	END

	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT t.ZX3_DataSetPK, t.ZX3_DataSetCode
	FROM RefCusConditionValue t
	JOIN inserted ON t.ZX3_PK = inserted.ZX3_PK
	UNION
	SELECT ZX3_DataSetPK, ZX3_DataSetCode
	FROM deleted

	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN @sourcePK ON RVC_ParentPK = PK AND RVC_ParentCode = TablePrefix
	WHERE RVC_IsPublished = 1

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO

CREATE TRIGGER RefCusConditionValue_DataProcessingResult_Delete
	ON RefCusConditionValue
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.ZX3_PK
	END
GO
